#!/usr/bin/env python3
"""Глава «Франция», пачка 1: легенды (4), Галлия (2), франки и Каролинги (6) — 12 уровней.

Реестр — docs/countries/france_registry.md; order/акт — PLAN в france_common.

    python3 tools/batches/france_1.py [repo_root]
"""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from france_common import (char, scene, actor, setf, remf, addr, rule, flag, nflag, texts, level, bait, run,
                           PARLEY, BATTLE)

def C(id, name, emoji, tags=None):
    return char(id, name, tags or [id], emoji)

CH, SC, RU, LV, TX = [], [], [], [], {}

def L(id, mood, cover, panels, scenes, chars, flags, goal, solution, acc, title, gtext, hint, intro, fact, source, rels=()):
    LV.append(level(id, mood, cover, panels, scenes, chars, flags, list(rels), goal, solution, acc))
    TX.update(texts(id, title, gtext, hint, intro, fact, source))

def S(id, name, slots, emoji, action, icon, roles, donor):
    SC.append(scene(id, name, [f"sig_{id}"], slots, emoji, action, icon, roles, donor))

def Rl(id, comment, actors, effects, n="", priority=10):
    RU.append(rule(f"{id}_sig{n}", comment, f"sig_{id}", actors, effects, priority))

def not_rel(rel, a, b):
    return {"not": {"relation": {"rel": rel, "from": a, "to": b}}}

